1	/**
2	 * @module features/tv-dashboard/model/useTvDashboardData
3	 *
4	 * Hook principal do Dashboard de Crise (painel TV `/tv`).
5	 *
6	 * Paraleliza as fontes de dados via React Query:
7	 * - vendas live (edge `degust-pos-financial`/flash-vendas) — polling 60s;
8	 * - vendas defasadas Linx (`historico_vendas`, último dia disponível);
9	 * - comparativo vs MESMO DIA da semana passada (`degust_vendas_diarias` /
10	 *   `historico_vendas`);
11	 * - metas por loja × dia da semana (`metas_vendas`) com pró-rata da janela;
12	 * - alertas de estoque (`estoque` × `produtos_master.ativo = true`);
13	 * - heartbeat de movimentações (`movimentacoes` de hoje);
14	 * - produção da fábrica (`daily_production` com loja_id NULL);
15	 * - top 5 produtos do dia da rede (`degust_vendas_diarias`).
16	 *
17	 * Nenhum `loja_id` é hardcoded: os canais são derivados em runtime de
18	 * `lojas` + `degust_stores` (Degust = live; demais lojas ativas = Linx
19	 * defasado; tipo "Fabrica" = card de fábrica).
20	 */
21	
22	import { useMemo } from 'react';
23	import { useQuery } from '@tanstack/react-query';
24	import { supabase } from '@/integrations/supabase/client';
25	import type {
26	  TvException,
27	  TvFactoryData,
28	  TvFactoryProduction,
29	  TvFreshness,
30	  TvMovementSummary,
31	  TvNetworkSummary,
32	  TvSalesChannel,
33	  TvSalesSnapshot,
34	  TvStoreData,
35	  TvExceptionsResult,
36	} from './types';
37	import {
38	  addDays,
39	  aggregateMovements,
40	  buildStockExceptions,
41	  buildStockSummary,
42	  classifyStaleness,
43	  classifyStoreRag,
44	  parseIsoDateLocal,
45	  pctOfFullDayTarget,
46	  pctOfProRataTarget,
47	  remapFlashLojaIds,
48	  sortAndLimitExceptions,
49	  toIsoDateLocal,
50	  topProductsFromDaily,
51	  weekOverWeekDelta,
52	  type FlashRow,
53	  type MovementAggregate,
54	  type StockDetail,
55	  type StockRow,
56	  type TvTopProduct,
57	} from './tvMath';
58	
59	// ─────────────────────────────────────────────────────────────────────────────
60	// Query keys + intervalos (exportados para o useTvRealtime invalidar)
61	// ─────────────────────────────────────────────────────────────────────────────
62	
63	/** Query keys do painel TV — usar SEMPRE estas referências para invalidar. */
64	export const tvDashboardKeys = {
65	  all: ['tv-dashboard'] as const,
66	  context: () => [...tvDashboardKeys.all, 'context'] as const,
67	  liveSales: () => [...tvDashboardKeys.all, 'live-sales'] as const,
68	  laggedSales: () => [...tvDashboardKeys.all, 'lagged-sales'] as const,
69	  lastWeekSales: () => [...tvDashboardKeys.all, 'last-week-sales'] as const,
70	  metas: () => [...tvDashboardKeys.all, 'metas'] as const,
71	  stock: () => [...tvDashboardKeys.all, 'stock'] as const,
72	  movements: () => [...tvDashboardKeys.all, 'movements'] as const,
73	  factoryProduction: () => [...tvDashboardKeys.all, 'factory-production'] as const,
74	  topProducts: () => [...tvDashboardKeys.all, 'top-products'] as const,
75	};
76	
77	/** Intervalos de atualização (ms) por classe de dado. */
78	export const TV_QUERY_INTERVALS = {
79	  /** Vendas live: polling 60s (acceptance: atualização em até 60s). */
80	  liveMs: 60_000,
81	  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
82	  slowMs: 300_000,
83	} as const;
84	
85	// ─────────────────────────────────────────────────────────────────────────────
86	// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
87	// ─────────────────────────────────────────────────────────────────────────────
88	
89	interface TvLoja {
90	  id: number;
91	  nome: string;
92	  tipo: string | null;
93	}
94	
95	interface TvContext {
96	  lojas: TvLoja[];
97	  /** Lojas com venda live (existem em `degust_stores`). */
98	  degustLojaIds: Set<number>;
99	  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
100	  degustCodeToLoja: Map<number, number>;
101	  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
102	  linxLojaIds: number[];
103	  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
104	  factoryLojaId: number | null;
105	}
106	
107	function isFactoryTipo(tipo: string | null): boolean {
108	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
109	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
110	}
111	
112	async function fetchTvContext(): Promise<TvContext> {
113	  const [lojasRes, degustRes] = await Promise.all([
114	    supabase
115	      .from('lojas')
116	      .select('id, nome, tipo')
117	      .eq('ativo', true)
118	      .order('id'),
119	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
120	  ]);
121	  if (lojasRes.error) throw lojasRes.error;
122	  if (degustRes.error) throw degustRes.error;
123	
124	  const lojas: TvLoja[] = lojasRes.data ?? [];
125	  const degustLojaIds = new Set<number>();
126	  const degustCodeToLoja = new Map<number, number>();
127	  for (const row of degustRes.data ?? []) {
128	    degustLojaIds.add(row.loja_id);
129	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
130	  }
131	
132	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
133	  const linxLojaIds = lojas
134	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
135	    .map((l) => l.id);
136	
137	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
138	}
139	
140	// ─────────────────────────────────────────────────────────────────────────────
141	// Vendas live (edge degust-pos-financial / flash-vendas)
142	// ─────────────────────────────────────────────────────────────────────────────
143	
144	/** Contrato da edge `degust-pos-financial` (campos usados pelo painel). */
145	interface DegustPosFinancialResponse {
146	  flash?: Array<{
147	    loja_id: number;
148	    nome_loja: string;
149	    total_vendas: number;
150	    total_cupons: number;
151	    ticket_medio: number;
152	    qtd_produtos: number;
153	    caixa_aberto: boolean;
154	    ultima_atualizacao: string | null;
155	  }>;
156	}
157	
158	async function fetchLiveSales(ctx: TvContext): Promise<FlashRow[]> {
159	  const today = toIsoDateLocal(new Date());
160	  const { data, error } = await supabase.functions.invoke<DegustPosFinancialResponse>(
161	    'degust-pos-financial',
162	    { body: { startDate: today, endDate: today } },
163	  );
164	  if (error) throw error;
165	  const flash: FlashRow[] = (data?.flash ?? []).map((f) => ({
166	    loja_id: f.loja_id,
167	    nome_loja: f.nome_loja,
168	    total_vendas: f.total_vendas,
169	    total_cupons: f.total_cupons,
170	    ticket_medio: f.ticket_medio,
171	    caixa_aberto: f.caixa_aberto,
172	    ultima_atualizacao: f.ultima_atualizacao,
173	  }));
174	  return remapFlashLojaIds(flash, ctx.degustCodeToLoja, ctx.degustLojaIds);
175	}
176	
177	// ─────────────────────────────────────────────────────────────────────────────
178	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
179	// ─────────────────────────────────────────────────────────────────────────────
180	
181	interface LaggedSales {
182	  lojaId: number;
183	  /** Último dia com venda registrada (YYYY-MM-DD). */
184	  dataReferencia: string;
185	  valor: number;
186	  quantidade: number;
187	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
188	  valorSemanaAnterior: number | null;
189	}
190	
191	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
192	  // 1) Último dia com dado para a loja
193	  const { data: latest, error: latestErr } = await supabase
194	    .from('historico_vendas')
195	    .select('data')
196	    .eq('loja_id', lojaId)
197	    .order('data', { ascending: false })
198	    .limit(1);
199	  if (latestErr) throw latestErr;
200	  const refDate = latest?.[0]?.data;
201	  if (!refDate) return null;
202	
203	  const prevDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
204	
205	  // 2) Vendas do dia de referência + mesmo dia da semana anterior
206	  const [curRes, prevRes] = await Promise.all([
207	    supabase
208	      .from('historico_vendas')
209	      .select('valor_total, quantidade')
210	      .eq('loja_id', lojaId)
211	      .eq('data', refDate)
212	      .limit(2000),
213	    supabase
214	      .from('historico_vendas')
215	      .select('valor_total')
216	      .eq('loja_id', lojaId)
217	      .eq('data', prevDate)
218	      .limit(2000),
219	  ]);
220	  if (curRes.error) throw curRes.error;
221	  if (prevRes.error) throw prevRes.error;
222	
223	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
224	  const quantidade = (curRes.data ?? []).reduce(
225	    (s, r) => s + (r.quantidade ?? 0),
226	    0,
227	  );
228	  const prevRows = prevRes.data ?? [];
229	  const valorSemanaAnterior =
230	    prevRows.length > 0
231	      ? prevRows.reduce((s, r) => s + (r.valor_total ?? 0), 0)
232	      : null;
233	
234	  return { lojaId, dataReferencia: refDate, valor, quantidade, valorSemanaAnterior };
235	}
236	
237	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
238	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
239	  return results.filter((r): r is LaggedSales => r !== null);
240	}
241	
242	// ─────────────────────────────────────────────────────────────────────────────
243	// Comparativo Degust: mesmo dia da semana passada (degust_vendas_diarias)
244	// ─────────────────────────────────────────────────────────────────────────────
245	
246	async function fetchDegustLastWeek(ctx: TvContext): Promise<Map<number, number>> {
247	  const lastWeekDate = toIsoDateLocal(addDays(new Date(), -7));
248	  const ids = [...ctx.degustLojaIds];
249	  const out = new Map<number, number>();
250	  if (ids.length === 0) return out;
251	  const { data, error } = await supabase
252	    .from('degust_vendas_diarias')
253	    .select('loja_id, valor_total')
254	    .eq('data', lastWeekDate)
255	    .in('loja_id', ids)
256	    .limit(5000);
257	  if (error) throw error;
258	  for (const row of data ?? []) {
259	    out.set(row.loja_id, (out.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
260	  }
261	  return out;
262	}
263	
264	// ─────────────────────────────────────────────────────────────────────────────
265	// Metas (loja × dia da semana, convenção JS Date.getDay(): 0=domingo)
266	// ─────────────────────────────────────────────────────────────────────────────
267	
268	async function fetchMetas(): Promise<Map<string, number>> {
269	  const { data, error } = await supabase
270	    .from('metas_vendas')
271	    .select('loja_id, dia_semana, valor_meta')
272	    .limit(1000);
273	  if (error) throw error;
274	  const out = new Map<string, number>();
275	  for (const row of data ?? []) {
276	    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
277	  }
278	  return out;
279	}
280	
281	function metaFor(
282	  metas: Map<string, number> | undefined,
283	  lojaId: number,
284	  date: Date,
285	): number | null {
286	  if (!metas) return null;
287	  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
288	}
289	
290	// ─────────────────────────────────────────────────────────────────────────────
291	// Estoque em alerta (JOIN com produtos ATIVOS — regra dura do projeto)
292	// ─────────────────────────────────────────────────────────────────────────────
293	
294	async function fetchStockAlerts(): Promise<StockRow[]> {
295	  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
296	  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas).
297	  const { data, error } = await supabase
298	    .from('estoque')
299	    .select(
300	      'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo)',
301	    )
302	    .eq('produto_master.ativo', true)
303	    .gt('quantidade_minima', 0)
304	    .or('oculto.is.null,oculto.eq.false')
305	    .limit(5000);
306	  if (error) throw error;
307	  return (data ?? []).map((row) => ({
308	    loja_id: row.loja_id,
309	    quantidade_atual: row.quantidade_atual,
310	    quantidade_minima: row.quantidade_minima,
311	    produtoNome: row.produto_master?.nome ?? '(sem nome)',
312	  }));
313	}
314	
315	// ─────────────────────────────────────────────────────────────────────────────
316	// Movimentações de hoje (heartbeat por loja)
317	// ─────────────────────────────────────────────────────────────────────────────
318	
319	async function fetchMovementsToday(): Promise<Map<number, MovementAggregate>> {
320	  const startOfDay = new Date();
321	  startOfDay.setHours(0, 0, 0, 0);
322	  const { data, error } = await supabase
323	    .from('movimentacoes')
324	    .select('loja_id, tipo_movimentacao, data_movimentacao')
325	    .gte('data_movimentacao', startOfDay.toISOString())
326	    .limit(10_000);
327	  if (error) throw error;
328	  return aggregateMovements(data ?? []);
329	}
330	
331	// ─────────────────────────────────────────────────────────────────────────────
332	// Produção da fábrica (daily_production com loja_id NULL = fábrica)
333	// ─────────────────────────────────────────────────────────────────────────────
334	
335	async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
336	  const today = toIsoDateLocal(new Date());
337	
338	  const loadDay = async (date: string) => {
339	    const { data, error } = await supabase
340	      .from('daily_production')
341	      .select('quantity')
342	      .is('loja_id', null)
343	      .eq('date', date)
344	      .limit(2000);
345	    if (error) throw error;
346	    return data ?? [];
347	  };
348	
349	  let refDate = today;
350	  let rows = await loadDay(today);
351	  if (rows.length === 0) {
352	    // Sem produção registrada hoje → mostra o último dia disponível
353	    const { data: latest, error } = await supabase
354	      .from('daily_production')
355	      .select('date')
356	      .is('loja_id', null)
357	      .lte('date', today)
358	      .order('date', { ascending: false })
359	      .limit(1);
360	    if (error) throw error;
361	    const lastDate = latest?.[0]?.date;
362	    if (!lastDate) return null;
363	    refDate = lastDate;
364	    rows = await loadDay(lastDate);
365	  }
366	
367	  return {
368	    dataReferencia: refDate,
369	    itens: rows.length,
370	    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
371	  };
372	}
373	
374	// ─────────────────────────────────────────────────────────────────────────────
375	// Top produtos do dia da rede (degust_vendas_diarias, dia mais recente)
376	// ─────────────────────────────────────────────────────────────────────────────
377	
378	async function fetchTopProducts(ctx: TvContext): Promise<TvTopProduct[]> {
379	  const ids = [...ctx.degustLojaIds];
380	  if (ids.length === 0) return [];
381	  const { data: latest, error: latestErr } = await supabase
382	    .from('degust_vendas_diarias')
383	    .select('data')
384	    .in('loja_id', ids)
385	    .order('data', { ascending: false })
386	    .limit(1);
387	  if (latestErr) throw latestErr;
388	  const refDate = latest?.[0]?.data;
389	  if (!refDate) return [];
390	
391	  const { data, error } = await supabase
392	    .from('degust_vendas_diarias')
393	    .select('degust_nome, quantidade, valor_total')
394	    .eq('data', refDate)
395	    .in('loja_id', ids)
396	    .limit(5000);
397	  if (error) throw error;
398	  return topProductsFromDaily(data ?? [], 5);
399	}
400	
401	// ─────────────────────────────────────────────────────────────────────────────
402	// Hook principal
403	// ─────────────────────────────────────────────────────────────────────────────
404	
405	/** Retorno do {@link useTvDashboardData}. */
406	export interface TvDashboardData {
407	  network: TvNetworkSummary | null;
408	  stores: TvStoreData[];
409	  factory: TvFactoryData | null;
410	  exceptions: TvExceptionsResult;
411	  topProducts: TvTopProduct[];
412	  freshness: TvFreshness;
413	  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
414	  isLoading: boolean;
415	  /** true quando o contexto falhou (painel não consegue montar). */
416	  isError: boolean;
417	}
418	
419	const EMPTY_MOVEMENT: TvMovementSummary = {
420	  entradas: 0,
421	  saidas: 0,
422	  ultimaBipagem: null,
423	};
424	
425	/**
426	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
427	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
428	 * `topProducts`, `freshness`). Vendas live re-buscam a cada 60s; o resto a
429	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
430	 */
431	export function useTvDashboardData(): TvDashboardData {
432	  const ctxQuery = useQuery({
433	    queryKey: tvDashboardKeys.context(),
434	    queryFn: fetchTvContext,
435	    staleTime: TV_QUERY_INTERVALS.slowMs,
436	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
437	  });
438	  const ctx = ctxQuery.data;
439	
440	  const liveQuery = useQuery({
441	    queryKey: tvDashboardKeys.liveSales(),
442	    queryFn: () => {
443	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
444	      return fetchLiveSales(ctx);
445	    },
446	    enabled: !!ctx,
447	    refetchInterval: TV_QUERY_INTERVALS.liveMs,
448	    staleTime: 30_000,
449	  });
450	
451	  const laggedQuery = useQuery({
452	    queryKey: tvDashboardKeys.laggedSales(),
453	    queryFn: () => {
454	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
455	      return fetchLaggedSales(ctx);
456	    },
457	    enabled: !!ctx,
458	    staleTime: TV_QUERY_INTERVALS.slowMs,
459	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
460	  });
461	
462	  const lastWeekQuery = useQuery({
463	    queryKey: tvDashboardKeys.lastWeekSales(),
464	    queryFn: () => {
465	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
466	      return fetchDegustLastWeek(ctx);
467	    },
468	    enabled: !!ctx,
469	    staleTime: TV_QUERY_INTERVALS.slowMs,
470	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
471	  });
472	
473	  const metasQuery = useQuery({
474	    queryKey: tvDashboardKeys.metas(),
475	    queryFn: fetchMetas,
476	    staleTime: TV_QUERY_INTERVALS.slowMs,
477	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
478	  });
479	
480	  const stockQuery = useQuery({
481	    queryKey: tvDashboardKeys.stock(),
482	    queryFn: fetchStockAlerts,
483	    staleTime: TV_QUERY_INTERVALS.slowMs,
484	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
485	  });
486	
487	  const movementsQuery = useQuery({
488	    queryKey: tvDashboardKeys.movements(),
489	    queryFn: fetchMovementsToday,
490	    staleTime: TV_QUERY_INTERVALS.slowMs,
491	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
492	  });
493	
494	  const factoryQuery = useQuery({
495	    queryKey: tvDashboardKeys.factoryProduction(),
496	    queryFn: fetchFactoryProduction,
497	    staleTime: TV_QUERY_INTERVALS.slowMs,
498	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
499	  });
500	
501	  const topQuery = useQuery({
502	    queryKey: tvDashboardKeys.topProducts(),
503	    queryFn: () => {
504	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
505	      return fetchTopProducts(ctx);
506	    },
507	    enabled: !!ctx,
508	    staleTime: TV_QUERY_INTERVALS.slowMs,
509	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
510	  });
511	
512	  return useMemo<TvDashboardData>(() => {
513	    const now = new Date();
514	    const todayIso = toIsoDateLocal(now);
515	
516	    const stockDetail: Map<number, StockDetail> = buildStockSummary(
517	      stockQuery.data ?? [],
518	    );
519	    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
520	    const flashByLoja = new Map<number, FlashRow>(
521	      (liveQuery.data ?? []).map((f) => [f.loja_id, f]),
522	    );
523	    const laggedByLoja = new Map<number, LaggedSales>(
524	      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
525	    );
526	    const lastWeekByLoja = lastWeekQuery.data ?? new Map<number, number>();
527	    const lojaNomeById = new Map<number, string>(
528	      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
529	    );
530	
531	    // ── Cards de loja ──
532	    const stores: TvStoreData[] = (ctx?.lojas ?? [])
533	      .filter((l) => !isFactoryTipo(l.tipo))
534	      .map((loja) => {
535	        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
536	          ? 'degust-live'
537	          : 'linx-lagged';
538	        const stock = stockDetail.get(loja.id);
539	        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;
540	
541	        let vendas: TvSalesSnapshot | null = null;
542	        let metaDia: number | null = null;
543	        let pctMeta: number | null = null;
544	        let deltaSemana: number | null = null;
545	
546	        if (channel === 'degust-live') {
547	          const flash = flashByLoja.get(loja.id);
548	          if (flash) {
549	            vendas = {
550	              valor: flash.total_vendas,
551	              cupons: flash.total_cupons,
552	              ticketMedio: flash.ticket_medio,
553	              dataReferencia: todayIso,
554	              isLive: true,
555	              caixaAberto: flash.caixa_aberto,
556	              atualizadoEm: flash.ultima_atualizacao,
557	            };
558	            metaDia = metaFor(metasQuery.data, loja.id, now);
559	            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
560	            deltaSemana = weekOverWeekDelta(
561	              flash.total_vendas,
562	              lastWeekByLoja.get(loja.id) ?? null,
563	            );
564	          }
565	        } else {
566	          const lagged = laggedByLoja.get(loja.id);
567	          if (lagged) {
568	            vendas = {
569	              valor: lagged.valor,
570	              cupons: null,
571	              ticketMedio: null,
572	              dataReferencia: lagged.dataReferencia,
573	              isLive: false,
574	              caixaAberto: null,
575	              atualizadoEm: null,
576	            };
577	            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
578	            const refDate = parseIsoDateLocal(lagged.dataReferencia);
579	            metaDia = metaFor(metasQuery.data, loja.id, refDate);
580	            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
581	            deltaSemana = weekOverWeekDelta(
582	              lagged.valor,
583	              lagged.valorSemanaAnterior,
584	            );
585	          }
586	        }
587	
588	        const rag = classifyStoreRag({
589	          stockOutCount: stock?.zerados ?? 0,
590	          stockLowCount: stock?.abaixoMinimo ?? 0,
591	          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
592	          isLiveChannel: channel === 'degust-live',
593	          lastMovementAt: movement.ultimaBipagem,
594	          now,
595	        });
596	
597	        return {
598	          lojaId: loja.id,
599	          nome: loja.nome,
600	          channel,
601	          vendas,
602	          metaDia,
603	          pctMeta,
604	          deltaSemana,
605	          estoque: {
606	            zerados: stock?.zerados ?? 0,
607	            abaixoMinimo: stock?.abaixoMinimo ?? 0,
608	          },
609	          movimentacao: movement,
610	          rag: rag.status,
611	          ragReasons: rag.reasons,
612	        };
613	      });
614	
615	    // ── Card da fábrica ──
616	    let factory: TvFactoryData | null = null;
617	    if (ctx?.factoryLojaId != null) {
618	      const fid = ctx.factoryLojaId;
619	      const stock = stockDetail.get(fid);
620	      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
621	      const rag = classifyStoreRag({
622	        stockOutCount: stock?.zerados ?? 0,
623	        stockLowCount: stock?.abaixoMinimo ?? 0,
624	        pctMetaProRata: null,
625	        isLiveChannel: false,
626	        lastMovementAt: movement.ultimaBipagem,
627	        now,
628	      });
629	      factory = {
630	        lojaId: fid,
631	        nome: lojaNomeById.get(fid) ?? 'Fábrica',
632	        producao: factoryQuery.data ?? null,
633	        expedicoes: movement,
634	        estoque: {
635	          zerados: stock?.zerados ?? 0,
636	          abaixoMinimo: stock?.abaixoMinimo ?? 0,
637	        },
638	        rag: rag.status,
639	        ragReasons: rag.reasons,
640	      };
641	    }
642	
643	    // ── Freshness ──
644	    const liveUpdatedAt =
645	      liveQuery.dataUpdatedAt > 0
646	        ? new Date(liveQuery.dataUpdatedAt).toISOString()
647	        : null;
648	    const stockUpdatedAt =
649	      stockQuery.dataUpdatedAt > 0
650	        ? new Date(stockQuery.dataUpdatedAt).toISOString()
651	        : null;
652	    const freshness: TvFreshness = {
653	      vendasLive: {
654	        updatedAt: liveUpdatedAt,
655	        level: classifyStaleness(liveUpdatedAt, TV_QUERY_INTERVALS.liveMs, now),
656	        expectedIntervalMs: TV_QUERY_INTERVALS.liveMs,
657	      },
658	      estoque: {
659	        updatedAt: stockUpdatedAt,
660	        level: classifyStaleness(stockUpdatedAt, TV_QUERY_INTERVALS.slowMs, now),
661	        expectedIntervalMs: TV_QUERY_INTERVALS.slowMs,
662	      },
663	      geradoEm: now.toISOString(),
664	    };
665	
666	    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
667	    const allExceptions: TvException[] = buildStockExceptions(
668	      stockDetail,
669	      lojaNomeById,
670	    );
671	    for (const store of stores) {
672	      const noMovement = store.ragReasons.find((r) =>
673	        r.startsWith('sem movimentação'),
674	      );
675	      if (noMovement) {
676	        allExceptions.push({
677	          id: `no-movement:${store.lojaId}`,
678	          kind: 'no-movement',
679	          severity: 'amber',
680	          lojaId: store.lojaId,
681	          lojaNome: store.nome,
682	          message: `${store.nome} ${noMovement} em horário comercial`,
683	        });
684	      }
685	    }
686	    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
687	      allExceptions.push({
688	        id: 'stale-data:vendas-live',
689	        kind: 'stale-data',
690	        severity: 'amber',
691	        lojaId: null,
692	        lojaNome: null,
693	        message: liveUpdatedAt
694	          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
695	          : 'Venda live ainda não carregou',
696	      });
697	    }
698	    const exceptions = sortAndLimitExceptions(allExceptions);
699	
700	    // ── Hero (rede) ──
701	    // Soma apenas lojas cujo dado é de HOJE (live) — não misturar dias.
702	    const liveStores = stores.filter(
703	      (s) => s.vendas?.isLive && s.vendas.dataReferencia === todayIso,
704	    );
705	    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
706	    const metasHoje = liveStores
707	      .map((s) => s.metaDia)
708	      .filter((m): m is number => m != null && m > 0);
709	    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
710	    const lastWeekTotal = liveStores.reduce(
711	      (s, st) => s + (lastWeekByLoja.get(st.lojaId) ?? 0),
712	      0,
713	    );
714	    const network: TvNetworkSummary | null = ctx
715	      ? {
716	          vendasHoje,
717	          metaDia,
718	          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
719	          deltaSemana: weekOverWeekDelta(vendasHoje, lastWeekTotal > 0 ? lastWeekTotal : null),
720	          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
721	          lojasLive: liveStores.length,
722	          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
723	        }
724	      : null;
725	
726	    return {
727	      network,
728	      stores,
729	      factory,
730	      exceptions,
731	      topProducts: topQuery.data ?? [],
732	      freshness,
733	      isLoading: ctxQuery.isLoading,
734	      isError: ctxQuery.isError,
735	    };
736	  }, [
737	    ctx,
738	    ctxQuery.isLoading,
739	    ctxQuery.isError,
740	    liveQuery.data,
741	    liveQuery.dataUpdatedAt,
742	    laggedQuery.data,
743	    lastWeekQuery.data,
744	    metasQuery.data,
745	    stockQuery.data,
746	    stockQuery.dataUpdatedAt,
747	    movementsQuery.data,
748	    factoryQuery.data,
749	    topQuery.data,
750	  ]);
751	}
