1	/**
2	 * @module features/tv-dashboard/ui/useMinuteClock
3	 *
4	 * Relógio do Painel TV: atualiza 1×/minuto, alinhado à virada do minuto
5	 * (design.md §3 zona 4 — sem segundos; segundos = movimento contínuo).
6	 */
7	
8	import { useEffect, useState } from 'react';
9	
10	/** Retorna o instante atual, re-renderizando uma vez por minuto. */
11	export function useMinuteClock(): Date {
12	  const [now, setNow] = useState(() => new Date());
13	
14	  useEffect(() => {
15	    let timer: number;
16	    const schedule = () => {
17	      // +80ms de folga pra garantir que já virou o minuto
18	      timer = window.setTimeout(() => {
19	        setNow(new Date());
20	        schedule();
21	      }, 60_000 - (Date.now() % 60_000) + 80);
22	    };
23	    schedule();
24	    return () => window.clearTimeout(timer);
25	  }, []);
26	
27	  return now;
28	}
