70	/**
71	 * Cor da barra de % meta a partir do ratio pró-rata (`%real / %esperado`,
72	 * em fração: 1.0 = exatamente no ritmo). Regra do design.md §1.6:
73	 * sage ≥ 0,9 · âmbar 0,75–0,9 · vermelho abaixo de 0,6 após 12:00
74	 * (entre 0,6 e 0,75 fica âmbar).
75	 * Ratio nulo (sem meta / antes da janela) fica sage — barra neutra.
76	 */
77	export function metaBarColorFromRatio(ratio: number | null, now: Date): TvBarColor {
78	  if (ratio == null) return 'sage';
79	  if (ratio >= 0.9) return 'sage';
80	  if (ratio >= 0.75) return 'amber';
81	  if (ratio < 0.6 && now.getHours() >= 12) return 'red';
82	  return 'amber';
83	}
84	
85	/** % esperado AGORA da meta do dia (posição do tick pró-rata), 0–100. */
86	export function expectedPctNow(now: Date): number {
87	  return Math.round(businessDayFraction(now) * 100);
88	}
89	
90	/** Limita um percentual de preenchimento de barra ao intervalo [0, 100]. */
91	export function clampPct(pct: number | null): number {
92	  if (pct == null || Number.isNaN(pct)) return 0;
93	  return Math.max(0, Math.min(100, pct));
94	}
