219	          style={{
220	            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
221	            top: tick.offset,
222	            width: tick.width,
223	            height: tick.height,
224	          }}
225	          data-testid="tv-meta-bar-tick"
226	        />
227	      )}
228	    </div>
229	  );
230	}
