 * design.md §1.6 regra 5: 10:00–22:00). AJUSTÁVEL: se o horário comercial
 * mudar, basta alterar aqui — pró-rata e "sem movimentação" derivam daqui.
 */
export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 10, end: 22 };

/**
 * Janela de produção da FÁBRICA (design.md §1.6 regra 5 + §5: 06:00–18:00).
 * Usada TANTO no RAG da fábrica quanto no alerta visual do card.
 */
export const TV_FACTORY_HOURS: TvBusinessHours = { start: 6, end: 18 };

/** Horas sem movimentação (dentro da janela) que tornam a LOJA âmbar. */
export const NO_MOVEMENT_THRESHOLD_HOURS = 3;

/** Horas sem bipagem (na janela de produção) que tornam a FÁBRICA âmbar (§5). */
export const FACTORY_NO_MOVEMENT_THRESHOLD_HOURS = 2;

/**
 * Ratio pró-rata (%real / %esperado, em %) abaixo do qual a venda live fica
 * ÂMBAR — nunca vermelho (design.md §1.6 regra 6: ratio menor que 0,75).
 */
export const LIVE_SALES_AMBER_THRESHOLD_PCT = 75;

/** Hora local a partir da qual a regra de venda fraca passa a valer (§1.6). */
export const LIVE_SALES_AMBER_FROM_HOUR = 11;

