export function weekOverWeekDelta(
  current: number,
  lastWeek: number | null | undefined,
): number | null {
  if (lastWeek == null || lastWeek <= 0) return null;
  return ((current - lastWeek) / lastWeek) * 100;
}

/**
 * Base PRÓ-RATEADA da semana passada para o delta do canal LIVE:
 * `lastWeek × businessDayFraction(now)` — o delta resultante compara hoje
 * (dia parcial) vs o MESMO PONTO do dia na semana passada, assumindo
 * distribuição intra-dia linear na janela (mesma fração usada no pró-rata
 * da meta, por consistência).
 *
 * Comparar dia parcial com dia completo inflava a queda de manhã.
 * Canal defasado (dia completo vs dia completo) NÃO usa esta função.
 *
 * Retorna null quando a base é ausente/não positiva ou antes da abertura
 * (fração 0 — não há ponto de comparação honesto).
 */
export function proRataLastWeekBase(
  lastWeek: number | null | undefined,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  if (lastWeek == null || lastWeek <= 0) return null;
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0) return null;
  return lastWeek * fraction;
}

