/**
 * Classificação RAG de uma unidade (management-by-exception).
 *
 * Regras (ordem de precedência):
 * - VERMELHO: existe item zerado em alerta (`stockOutCount > 0`) OU a venda
 *   live está abaixo de {@link LIVE_SALES_RED_THRESHOLD_PCT}% do esperado
 *   pró-rata (somente canal live e quando há meta → pct != null).
 * - ÂMBAR: existem itens abaixo do mínimo (`stockLowCount > 0`) OU a unidade
 *   está sem movimentação há mais de {@link NO_MOVEMENT_THRESHOLD_HOURS}h
 *   dentro da janela de funcionamento.
 * - OK: nenhum desvio — tela calma, sem cor.
 */
export function classifyStoreRag(input: StoreRagInput): {
  status: TvRagStatus;
  reasons: string[];
} {
  const hours = input.hours ?? TV_BUSINESS_HOURS;
  const reasons: string[] = [];

  // ── Vermelho ──
  if (input.stockOutCount > 0) {
    reasons.push(
      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
    );
  }
  if (
    input.isLiveChannel &&
    input.pctMetaProRata !== null &&
    input.pctMetaProRata < LIVE_SALES_RED_THRESHOLD_PCT
  ) {
    reasons.push(
      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
    );
  }
  if (reasons.length > 0) return { status: 'red', reasons };

  // ── Âmbar ──
  if (input.stockLowCount > 0) {
    reasons.push(
      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
    );
  }
  const gapHours = hoursWithoutMovementInWindow(
    input.lastMovementAt,
    input.now,
    hours,
  );
  if (gapHours !== null && gapHours > NO_MOVEMENT_THRESHOLD_HOURS) {
    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
  }
  if (reasons.length > 0) return { status: 'amber', reasons };

  return { status: 'ok', reasons: [] };
}

input.new_string:
/**
 * Classificação RAG de uma unidade (management-by-exception).
 *
 * Regras (design.md §1.6, ordem de precedência):
 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
 *   manhã, quando o pró-rata ainda é instável).
 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
 *   movimentação há mais que o threshold dentro da janela OU venda live com
 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
 *   em canal live e com meta cadastrada (pct != null).
 * - OK: nenhum desvio — tela calma, sem cor.
 */
export function classifyStoreRag(input: StoreRagInput): {
  status: TvRagStatus;
  reasons: string[];
} {
  const hours = input.hours ?? TV_BUSINESS_HOURS;
  const noMovementThreshold =
    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
  const reasons: string[] = [];

  // ── Vermelho: só ruptura (item zerado em alerta) ──
  if (input.stockOutCount > 0) {
    reasons.push(
      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
    );
    return { status: 'red', reasons };
  }

  // ── Âmbar ──
  if (input.stockLowCount > 0) {
    reasons.push(
      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
    );
  }
  const gapHours = hoursWithoutMovementInWindow(
    input.lastMovementAt,
    input.now,
    hours,
  );
  if (gapHours !== null && gapHours > noMovementThreshold) {
    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
  }
  if (
    input.isLiveChannel &&
    input.pctMetaProRata !== null &&
    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
  ) {
    reasons.push(
      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
    );
  }
  if (reasons.length > 0) return { status: 'amber', reasons };

  return { status: 'ok', reasons: [] };
}

/** Entrada de {@link buildNoMovementException}. */
export interface NoMovementExceptionInput {
  lojaId: number;
  lojaNome: string;
  /** Timestamp da última movimentação (ISO/Date), ou null se nenhuma hoje. */
  lastMovementAt: Date | string | null;
  now: Date;
  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
  hours?: TvBusinessHours;
  /** Threshold em horas (default lojas 3h; fábrica 2h). */
  thresholdHours?: number;
}

/**
 * Exceção "sem movimentação" derivada DIRETO do dado estruturado (timestamp
 * da última bipagem + janela), nunca por parsing de string de ragReasons —
 * por isso INDEPENDE da cor do card (aparece mesmo com card vermelho) e
 * cobre também a fábrica (janela/threshold próprios via parâmetros).
 * Retorna null quando não há gap acima do threshold dentro da janela.
 */
export function buildNoMovementException(
  input: NoMovementExceptionInput,
): TvException | null {
  const threshold = input.thresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
  const gap = hoursWithoutMovementInWindow(
    input.lastMovementAt,
    input.now,
    input.hours ?? TV_BUSINESS_HOURS,
  );
  if (gap === null || gap <= threshold) return null;
  return {
    id: `no-movement:${input.lojaId}`,
    kind: 'no-movement',
    severity: 'amber',
    lojaId: input.lojaId,
    lojaNome: input.lojaNome,
    message: `${input.lojaNome} sem movimentação há ${Math.floor(gap)}h em horário comercial`,
  };
}

