export function classifyStaleness(
  lastUpdatedAt: Date | string | number | null | undefined,
  expectedIntervalMs: number,
  now: Date,
): TvFreshnessLevel {
  if (lastUpdatedAt == null) return 'very-stale';
  const ts = new Date(lastUpdatedAt).getTime();
  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
  const age = now.getTime() - ts;
  if (age < 2 * expectedIntervalMs) return 'fresh';
  if (age < 6 * expectedIntervalMs) return 'stale';
  return 'very-stale';
}

/**
 * Monta o freshness consolidado a partir dos timestamps CRUS de última
 * atualização bem-sucedida (React Query `dataUpdatedAt`, em ms; 0 = nunca).
 *
 * A classificação depende de `now`: o chamador DEVE reavaliar com um relógio
 * que AVANÇA (tick de minuto), para que um outage total — nenhuma query
 * devolvendo dado novo — escale o chip pra âmbar quando `dataUpdatedAt`
 * parar de avançar além de 2× o intervalo esperado.
 */
export function buildFreshness(
  liveUpdatedAtMs: number,
  stockUpdatedAtMs: number,
  intervals: { liveMs: number; slowMs: number },
  now: Date,
): TvFreshness {
  const liveUpdatedAt =
    liveUpdatedAtMs > 0 ? new Date(liveUpdatedAtMs).toISOString() : null;
  const stockUpdatedAt =
    stockUpdatedAtMs > 0 ? new Date(stockUpdatedAtMs).toISOString() : null;
  return {
    vendasLive: {
      updatedAt: liveUpdatedAt,
      level: classifyStaleness(liveUpdatedAt, intervals.liveMs, now),
      expectedIntervalMs: intervals.liveMs,
    },
    estoque: {
      updatedAt: stockUpdatedAt,
      level: classifyStaleness(stockUpdatedAt, intervals.slowMs, now),
      expectedIntervalMs: intervals.slowMs,
    },
    geradoEm: now.toISOString(),
  };
}

