/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
export function formatLaggedDateLabel(isoDate: string): string {
  const d = parseIsoDateLocal(isoDate);
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `até ${dd}/${mm}`;
}

/**
 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
 */
export function parseBrDateTime(value: string | null | undefined): Date | null {
  if (!value) return null;
  const m = value.match(
    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
  );
  if (m) {
    const [, dd, mm, yyyy, hh, mi, ss] = m;
    const month = Number(mm);
    const day = Number(dd);
    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
    return new Date(
      Number(yyyy),
      month - 1,
      day,
      Number(hh),
      Number(mi),
      ss ? Number(ss) : 0,
    );
  }
  const fallback = new Date(value);
  return Number.isNaN(fallback.getTime()) ? null : fallback;
}

