// ─────────────────────────────────────────────────────────────────────────────
// Paginação PostgREST (loop genérico com fetcher injetado — sem I/O próprio)
// ─────────────────────────────────────────────────────────────────────────────

/** Página de resultado mínima consumida por {@link fetchAllPages}. */
export interface TvPageResult<T> {
  data: T[] | null;
  error: { message: string } | null;
}

/**
 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
 *
 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
 * sobreporem entre requests.
 */
export async function fetchAllPages<T>(
  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
  pageSize = 1000,
): Promise<T[]> {
  const all: T[] = [];
  let offset = 0;
  for (;;) {
    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
    if (error) throw error;
    const rows = data ?? [];
    all.push(...rows);
    if (rows.length < pageSize) return all;
    offset += pageSize;
  }
}

