/**
 * @module features/tv-dashboard/model/useMinuteClock
 *
 * Tick de minuto do Painel TV, alinhado à virada do minuto. Duplo papel:
 * - relógio do hero (design.md §3 zona 4 — sem segundos);
 * - "now" que AVANÇA dentro do `useTvDashboardData`, para staleness/RAG
 *   escalarem mesmo em outage total (nenhuma query devolvendo dado novo).
 */

import { useEffect, useState } from 'react';

/** Retorna o instante atual, re-renderizando uma vez por minuto. */
export function useMinuteClock(): Date {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    let timer: number;
    const schedule = () => {
      // +80ms de folga pra garantir que já virou o minuto
      timer = window.setTimeout(() => {
        setNow(new Date());
        schedule();
      }, 60_000 - (Date.now() % 60_000) + 80);
    };
    schedule();
    return () => window.clearTimeout(timer);
  }, []);

  return now;
}

