async function fetchTopProducts(ctx: TvContext): Promise<TvTopProduct[]> {
  const ids = [...ctx.degustLojaIds];
  if (ids.length === 0) return [];
  const { data: latest, error: latestErr } = await supabase
    .from('degust_vendas_diarias')
    .select('data')
    .in('loja_id', ids)
    .order('data', { ascending: false })
    .limit(1);
  if (latestErr) throw latestErr;
  const refDate = latest?.[0]?.data;
  if (!refDate) return [];

  const { data, error } = await supabase
    .from('degust_vendas_diarias')
    .select('degust_nome, quantidade, valor_total')
    .eq('data', refDate)
    .in('loja_id', ids)
    .limit(5000);
  if (error) throw error;
  return topProductsFromDaily(data ?? [], 5);
}

