    const updated = at(14).getTime();
    const f = buildFreshness(updated, updated, intervals, at(14, 1));
    expect(f.vendasLive.level).toBe('fresh');
    expect(f.vendasLive.updatedAt).toBe(new Date(updated).toISOString());
    expect(f.vendasLive.expectedIntervalMs).toBe(intervals.liveMs);
  });

  it('escala pra stale/very-stale quando o relógio avança SEM dado novo (outage total)', () => {
    const updated = at(14).getTime();
    // Mesmo updatedAt: só o "now" avança (tick de minuto) → chip âmbar
    expect(
      buildFreshness(updated, updated, intervals, at(14, 3)).vendasLive.level,
    ).toBe('stale');
    expect(
      buildFreshness(updated, updated, intervals, at(14, 30)).vendasLive.level,
    ).toBe('very-stale');
  });

  it('estoque usa o intervalo lento na classificação', () => {
    const updated = at(14).getTime();
    const f = buildFreshness(updated, updated, intervals, at(14, 3));
    expect(f.estoque.level).toBe('fresh'); // 3min < 2×5min
  });

  it('nunca carregou (dataUpdatedAt = 0) → very-stale com timestamp null', () => {
    const f = buildFreshness(0, 0, intervals, at(14));
    expect(f.vendasLive.updatedAt).toBeNull();
    expect(f.vendasLive.level).toBe('very-stale');
  });
});

describe('parseBrDateTime', () => {
  it('parseia "DD/MM/YYYY HH:mm:ss" com dia > 12 (new Date falharia)', () => {
    const d = parseBrDateTime('25/12/2026 09:05:30');
    expect(d?.getFullYear()).toBe(2026);
    expect(d?.getMonth()).toBe(11);
    expect(d?.getDate()).toBe(25);
    expect(d?.getHours()).toBe(9);
    expect(d?.getMinutes()).toBe(5);
    expect(d?.getSeconds()).toBe(30);
  });

  it('aceita segundos opcionais', () => {
    const d = parseBrDateTime('04/06/2026 14:32');
    expect(d?.getDate()).toBe(4);
    expect(d?.getMonth()).toBe(5);
    expect(d?.getMinutes()).toBe(32);
  });

  it('rejeita dia/mês fora de faixa', () => {
    expect(parseBrDateTime('32/01/2026 10:00:00')).toBeNull();
    expect(parseBrDateTime('01/13/2026 10:00:00')).toBeNull();
  });

  it('faz fallback pro parse nativo em ISO', () => {
    const d = parseBrDateTime('2026-06-04T14:32:00');
    expect(d?.getHours()).toBe(14);
  });

  it('entrada inválida/ausente → null', () => {
    expect(parseBrDateTime('not-a-date')).toBeNull();
    expect(parseBrDateTime(null)).toBeNull();
    expect(parseBrDateTime(undefined)).toBeNull();
    expect(parseBrDateTime('')).toBeNull();
  });
});

describe('fetchAllPages (paginação contra o corte de 1000 do PostgREST)', () => {
  it('pagina em loop até a página vir menor que o pageSize', async () => {
    const all = Array.from({ length: 7 }, (_, i) => i + 1);
    const calls: Array<[number, number]> = [];
    const rows = await fetchAllPages<number>(async (from, to) => {
      calls.push([from, to]);
      return { data: all.slice(from, to + 1), error: null };
    }, 3);
    expect(rows).toEqual(all);
    expect(calls).toEqual([
      [0, 2],
      [3, 5],
      [6, 8],
    ]);
  });

  it('total múltiplo exato do pageSize termina na página vazia seguinte', async () => {
    const all = [1, 2, 3];
    const rows = await fetchAllPages<number>(
      async (from, to) => ({ data: all.slice(from, to + 1), error: null }),
      3,
    );
    expect(rows).toEqual(all);
  });

  it('uma página única menor que o pageSize faz UMA chamada', async () => {
    let calls = 0;
    const rows = await fetchAllPages<number>(async (from, to) => {
      calls += 1;
      return { data: [1, 2].slice(from, to + 1), error: null };
    }, 1000);
    expect(rows).toEqual([1, 2]);
    expect(calls).toBe(1);
  });

  it('propaga erro do fetcher (fail fast, sem truncar silencioso)', async () => {
    await expect(
      fetchAllPages<number>(async () => ({ data: null, error: { message: 'boom' } }), 3),
    ).rejects.toMatchObject({ message: 'boom' });
  });
});

