describe('TvMetasPage — limpar célula remove a meta', () => {
  it('célula que TINHA meta e foi esvaziada vai no upsert com valor_meta=0', async () => {
    renderPage();
    const input = await screen.findByLabelText('Meta de Momma Asa Sul — Seg');
    expect(input).toHaveDisplayValue('4000');

    fireEvent.change(input, { target: { value: '' } });
    fireEvent.click(screen.getByRole('button', { name: /salvar metas/i }));

    await waitFor(() => expect(upsertSpy).toHaveBeenCalled());
    const rows = upsertSpy.mock.calls[0][0] as Array<{
      loja_id: number;
      dia_semana: number;
      valor_meta: number;
    }>;
    // 0 semanticamente = sem meta (data layer trata <= 0 como null)
    expect(rows).toContainEqual({ loja_id: 2, dia_semana: 1, valor_meta: 0 });
    // Células que sempre estiveram vazias NÃO são enviadas
    expect(rows).toHaveLength(1);
  });

  it('célula esvaziada que nunca teve meta não dispara upsert (botão desabilitado)', async () => {
    renderPage();
    const input = await screen.findByLabelText('Meta de Momma Asa Sul — Seg');

    // Esvazia a única meta persistida e também mexe numa célula virgem
    fireEvent.change(input, { target: { value: '' } });
    const virgin = screen.getByLabelText('Meta de Momma Águas Claras — Dom');
    fireEvent.change(virgin, { target: { value: '' } });
    fireEvent.click(screen.getByRole('button', { name: /salvar metas/i }));

    await waitFor(() => expect(upsertSpy).toHaveBeenCalled());
    const rows = upsertSpy.mock.calls[0][0] as Array<{ loja_id: number }>;
    expect(rows).toHaveLength(1); // só a célula que tinha meta no banco
  });
});

